   {tab==="editor"&&<section className="superadmin-editor-panel" style={{background:"#fff",border:"1px solid #e6ebf2",borderRadius:18,padding:"clamp(16px,3vw,28px)",maxWidth:980}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:22}}><div><h2 style={{fontSize:20,margin:"0 0 6px"}}>{cloneSource?"إنشاء متجر جديد بنفس القطاع":editing?"تعديل وإدارة المتجر":"إنشاء متجر جديد"}</h2><p style={{fontSize:12,color:"#8290a3",margin:0}}>إعداد الرابط وحساب المدير والاشتراك فقط. هوية المتجر يضبطها صاحبه من لوحة متجره.</p></div><button onClick={()=>navigateTab("stores")} style={{display:"flex",alignItems:"center",gap:6,border:0,background:"transparent",color:"#64748b",cursor:"pointer"}}><ArrowRight size={16}/> رجوع</button></div><h3 style={{fontSize:15,borderBottom:"1px solid #edf0f4",paddingBottom:12}}>معلومات المتجر والنشاط</h3><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(220px,1fr))",gap:14}}><label><span style={label}>الاسم الظاهر</span><input style={field} value={form.name} onChange={e=>F({...form,name:e.target.value})} placeholder="اسم المتجر"/></label><label><span style={label}>الباقة</span><select style={field} value={form.planId||""} onChange={e=>F({...form,planId:e.target.value})}><option value="">بدون باقة محددة</option>{(consoleData.plans||[]).map((pl:any)=><option key={pl._id} value={pl._id}>{pl.name}</option>)}</select></label><label><span style={label}>قطاع النشاط</span><select style={field} value={form.industry||"general"} onChange={e=>F({...form,industry:e.target.value})}>{industries.map(x=><option value={x.value} key={x.value}>{x.label}</option>)}</select></label><label><span style={label}>الرابط المختصر (Slug)</span><input style={{...field,direction:"ltr"}} value={form.slug} disabled={!!editing} onChange={e=>F({...form,slug:e.target.value.toLowerCase().replace(/[^a-z0-9-]/g,"-")})} placeholder="my-store"/>{editing&&<small style={{color:"#94a3b8"}}>الرابط لا يتغير بعد إنشاء المتجر.</small>}</label></div><h3 style={{fontSize:15,borderBottom:"1px solid #edf0f4",paddingBottom:12,marginTop:25}}>حساب صاحب المتجر</h3><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(220px,1fr))",gap:14}}><label><span style={label}>اسم المستخدم</span><input style={field} value={form.username} onChange={e=>F({...form,username:e.target.value})}/></label><label><span style={label}>{editing?"كلمة مرور جديدة (اختياري)":"كلمة المرور"}</span><input style={field} type="password" value={form.password} onChange={e=>F({...form,password:e.target.value})} placeholder={editing?"اتركها فارغة للإبقاء على الحالية":"10 أحرف على الأقل"}/></label></div>{editing&&<div style={{fontSize:12,color:"#64748b",background:"#f6f8fb",padding:12,borderRadius:10,marginTop:12}}>لتغيير كلمة مرور المشترك، اكتب كلمة مرور جديدة هنا ثم احفظ. لا يتم عرض كلمة المرور الحالية لأسباب أمنية.</div>}<h3 style={{fontSize:15,borderBottom:"1px solid #edf0f4",paddingBottom:12,marginTop:25}}>الاشتراك</h3><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:14}}>{!editing?<label><span style={label}>مدة الاشتراك</span><select style={field} value={form.months} onChange={e=>F({...form,months:e.target.value})}>{[1,2,3,6,9,12,18,24,36,48,60].map(n=><option value={n} key={n}>{n===12?"سنة واحدة":n===24?"سنتان":n+" شهر"}</option>)}<option value="custom">مدة مخصصة</option></select>{form.months==="custom"&&<input style={{...field,marginTop:8}} type="number" min="1" max="60" placeholder="عدد الأشهر (1–60)" value={form.customMonths} onChange={e=>F({...form,customMonths:e.target.value})}/>}</label>:<><div><span style={label}>تاريخ الانتهاء الحالي</span><div style={{...field,background:"#f8fafc"}}>{stores.find(s=>s.slug===editing)?.subscription?.endsAt?new Date(stores.find(s=>s.slug===editing)!.subscription!.endsAt).toLocaleDateString("ar-JO"):"غير محدد"}</div></div><label><span style={label}>تجديد الاشتراك لمدة</span><select style={field} value={form.months} onChange={e=>F({...form,months:e.target.value})}><option value="">اختر المدة</option>{[1,2,3,6,9,12,18,24,36,48,60].map(n=><option value={n} key={n}>{n===12?"سنة واحدة":n===24?"سنتان":n+" شهر"}</option>)}<option value="custom">مدة مخصصة</option></select>{form.months==="custom"&&<input style={{...field,marginTop:8}} type="number" min="1" max="60" placeholder="عدد الأشهر (1–60)" value={form.customMonths} onChange={e=>F({...form,customMonths:e.target.value})}/>}</label><button onClick={renew} disabled={!form.months||busy} style={{alignSelf:"end",padding:12,border:0,borderRadius:11,background:"#eaf5ee",color:"#237448",fontWeight:800,cursor:"pointer"}}>تجديد الاشتراك</button></>}</div><div style={{display:"flex",gap:10,flexWrap:"wrap",marginTop:28}}><button onClick={saveStore} disabled={busy} style={{display:"flex",alignItems:"center",gap:8,padding:"13px 20px",border:0,borderRadius:12,background:"#124B32",color:"#fff",fontWeight:800,cursor:"pointer"}}><Save size={17}/>{busy?"جارٍ الحفظ…":editing?"حفظ كل التعديلات":"إنشاء المتجر"}</button>{editing&&<button onClick={()=>updateStore(editing,{status:stores.find(s=>s.slug===editing)?.status==="active"?"disabled":"active"})} style={{padding:"13px 18px",border:"1px solid #e0e6ee",borderRadius:12,background:"#fff",color:"#52647d",cursor:"pointer"}}>{stores.find(s=>s.slug===editing)?.status==="active"?"إيقاف المتجر":"تفعيل المتجر"}</button>}</div></section>}
   {tab==="subscriptions"&&<section style={{background:"#fff",border:"1px solid #e6ebf2",borderRadius:17,padding:20}}><h2 style={{fontSize:18,marginTop:0}}>متابعة الاشتراكات</h2><div style={{display:"grid",gap:10}}>{stores.map(s=>{const end=s.subscription?.endsAt?new Date(s.subscription.endsAt):null;const isExpired=!!end&&end<new Date();const days=end?Math.ceil((end.getTime()-Date.now())/86400000):null;return <div key={s.slug} style={{display:"flex",alignItems:"center",gap:14,flexWrap:"wrap",padding:14,border:"1px solid #edf0f4",borderRadius:13}}><div style={{flex:1,minWidth:150}}><b>{s.name}</b><div style={{fontSize:11,color:"#8491a4",marginTop:4}}>/{s.slug}</div></div><div><small style={{display:"block",color:"#8793a4"}}>ينتهي في</small><b style={{fontSize:13}}>{end?end.toLocaleDateString("ar-JO"):"غير محدد"}</b></div><div><small style={{display:"block",color:"#8793a4"}}>الحالة</small><b style={{fontSize:13,color:isExpired?"#bd4545":days!==null&&days<=7?"#b7791f":"#238451"}}>{isExpired?"منتهي":days!==null&&days<=7?"قارب على الانتهاء":"ساري"}</b></div><button onClick={()=>startEdit(s)} style={{padding:"9px 12px",border:0,borderRadius:10,background:"#edf2f8",color:"#124B32",fontWeight:700,cursor:"pointer"}}>إدارة وتجديد</button></div>})}</div></section>}

