     <div className="plans-editor-footer"><label className="plans-active"><input type="checkbox" checked={planForm.active!==false} onChange={e=>PF({...planForm,active:e.target.checked})}/> الباقة متاحة للاستخدام</label><div><button className="plans-reset" onClick={()=>PF({id:"",name:"",price:0,currency:"JOD",billingPeriod:"monthly",limits:{items:100,branches:1,languages:1,users:1},features:{onlineOrders:false,qr:true,reports:false,customDomain:false,multipleLanguages:false},active:true,sortOrder:0})}>تفريغ النموذج</button><button className="plans-save" disabled={busy||!planForm.id||!planForm.name} onClick={async()=>{B(true);E("");N("");try{const r=await fetch("/api/platform/console",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"savePlan",...planForm})});const d=await r.json();if(!r.ok)throw new Error(d.error);N("تم حفظ الباقة في قاعدة البيانات");await load();}catch(e:any){E(e.message||"تعذر حفظ الباقة")}finally{B(false)}}}><Save size={17}/> حفظ الباقة</button></div></div>
